// Package geo is the offline basemap for Sakuna Bantay cards.
//
// The compact embedded file basemap.bin is generated by go/tools/mkgeo from
// assets/geo/geoBoundaries-PHL-ADM2_simplified.geojson (87 provinces/NCR
// districts, property shapeName; CC BY 3.0 IGO) and
// assets/geo/ne_50m_land.geojson (Natural Earth, public domain context land):
// clipped to lon 114–130 / lat 3–23, Douglas–Peucker simplified (~0.005°),
// quantized to uint16, packed binary (< 1.5 MB, committed).
//
// This package decodes it (Load), offers an equirectangular projection with
// cos(lat) correction mapping a lon/lat bbox onto a pixel rect (Proj), and a
// name-matching helper (NormalizeName) mapping CAP areaDesc names onto
// basemap province names.
package geo

import (
	"bytes"
	_ "embed"
	"encoding/binary"
	"fmt"
	"math"
	"strings"
)

//go:embed basemap.bin
var basemapBin []byte

// Clip box (must match go/tools/mkgeo).
const (
	ClipMinLon = 114.0
	ClipMaxLon = 130.0
	ClipMinLat = 3.0
	ClipMaxLat = 23.0
)

// Pt is a lon/lat point in degrees.
type Pt struct {
	Lon, Lat float64
}

// Province is one ADM2 area: a shapeName plus its polygons (rings).
type Province struct {
	Name  string
	Polys [][]Pt
}

// Basemap holds the decoded provinces + context land polygons.
type Basemap struct {
	Provinces []Province
	Land      [][]Pt
	MinLon    float64
	MinLat    float64
	MaxLon    float64
	MaxLat    float64
}

// ProvinceByNorm returns the province whose normalized name equals norm, or
// nil. Build the lookup once with Index for repeated queries.
func (b *Basemap) ProvinceByNorm(norm string) *Province {
	for i := range b.Provinces {
		if NormalizeName(b.Provinces[i].Name) == norm {
			return &b.Provinces[i]
		}
	}
	return nil
}

// Index maps normalized province names to provinces for shading lookups.
func (b *Basemap) Index() map[string]*Province {
	m := make(map[string]*Province, len(b.Provinces))
	for i := range b.Provinces {
		m[NormalizeName(b.Provinces[i].Name)] = &b.Provinces[i]
	}
	return m
}

// Load decodes the embedded basemap.bin.
func Load() (*Basemap, error) {
	return Decode(basemapBin)
}

// Decode decodes one basemap.bin payload (exported for round-trip tests).
func Decode(data []byte) (*Basemap, error) {
	r := bytes.NewReader(data)
	magic := make([]byte, 7)
	if _, err := r.Read(magic); err != nil || string(magic) != "SBGEO1\n" {
		return nil, fmt.Errorf("geo: bad magic %q", magic)
	}
	var bb [4]float64
	if err := binary.Read(r, binary.LittleEndian, &bb); err != nil {
		return nil, fmt.Errorf("geo: bad bbox: %w", err)
	}
	b := &Basemap{MinLon: bb[0], MinLat: bb[1], MaxLon: bb[2], MaxLat: bb[3]}
	uvarint := func() (uint64, error) { return binary.ReadUvarint(r) }
	nProv, err := uvarint()
	if err != nil {
		return nil, fmt.Errorf("geo: bad province count: %w", err)
	}
	for i := uint64(0); i < nProv; i++ {
		nl, err := binary.ReadUvarint(r)
		if err != nil {
			return nil, fmt.Errorf("geo: bad name len: %w", err)
		}
		name := make([]byte, nl)
		if _, err := r.Read(name); err != nil {
			return nil, fmt.Errorf("geo: bad name: %w", err)
		}
		np, err := binary.ReadUvarint(r)
		if err != nil {
			return nil, fmt.Errorf("geo: bad poly count: %w", err)
		}
		var polys [][]Pt
		for j := uint64(0); j < np; j++ {
			ring, err := readRing(r, uvarint, b)
			if err != nil {
				return nil, err
			}
			polys = append(polys, ring)
		}
		b.Provinces = append(b.Provinces, Province{Name: string(name), Polys: polys})
	}
	nLand, err := binary.ReadUvarint(r)
	if err != nil {
		return nil, fmt.Errorf("geo: bad land count: %w", err)
	}
	for i := uint64(0); i < nLand; i++ {
		ring, err := readRing(r, uvarint, b)
		if err != nil {
			return nil, err
		}
		b.Land = append(b.Land, ring)
	}
	return b, nil
}

func readRing(r *bytes.Reader, uvarint func() (uint64, error), b *Basemap) ([]Pt, error) {
	n, err := uvarint()
	if err != nil {
		return nil, fmt.Errorf("geo: bad ring len: %w", err)
	}
	ring := make([]Pt, 0, n)
	for i := uint64(0); i < n; i++ {
		qx, err := uvarint()
		if err != nil {
			return nil, fmt.Errorf("geo: bad qx: %w", err)
		}
		qy, err := uvarint()
		if err != nil {
			return nil, fmt.Errorf("geo: bad qy: %w", err)
		}
		ring = append(ring, Pt{
			Lon: b.MinLon + float64(qx)/65535*(b.MaxLon-b.MinLon),
			Lat: b.MinLat + float64(qy)/65535*(b.MaxLat-b.MinLat),
		})
	}
	return ring, nil
}

// --- Projection ---

// BBox is a lon/lat bounding box in degrees.
type BBox struct {
	MinLon, MinLat, MaxLon, MaxLat float64
}

// Proj maps lon/lat onto a pixel rect, equirectangular with cos(refLat)
// correction so a degree of longitude is foreshortened like on the globe.
type Proj struct {
	MinLon, MinLat, MaxLon, MaxLat float64
	X, Y, W, H                     float64
	CosRef                         float64
	SX, SY                         float64 // px per (corrected) degree
}

// Fit maps bbox onto the pixel rect (x, y, w, h), expanding the bbox on the
// short axis so the aspect matches: SX == SY, no distortion. refLat
// defaults to the bbox mid latitude when 0.
func (b BBox) Fit(x, y, w, h float64, refLat float64) Proj {
	if refLat == 0 {
		refLat = (b.MinLat + b.MaxLat) / 2
	}
	cosRef := math.Cos(refLat * math.Pi / 180)
	spanX := (b.MaxLon - b.MinLon) * cosRef
	spanY := b.MaxLat - b.MinLat
	if spanX <= 0 || spanY <= 0 || w <= 0 || h <= 0 {
		return Proj{MinLon: b.MinLon, MinLat: b.MinLat, MaxLon: b.MaxLon, MaxLat: b.MaxLat,
			X: x, Y: y, W: w, H: h, CosRef: cosRef, SX: 1, SY: 1}
	}
	scale := math.Min(w/spanX, h/spanY)
	// Expand the short axis (in degrees) so the fitted box fills the rect.
	needX := w / scale / cosRef
	needY := h / scale
	midLon := (b.MinLon + b.MaxLon) / 2
	midLat := (b.MinLat + b.MaxLat) / 2
	minLon, maxLon := b.MinLon, b.MaxLon
	minLat, maxLat := b.MinLat, b.MaxLat
	if (maxLon - minLon) < needX {
		minLon, maxLon = midLon-needX/2, midLon+needX/2
	}
	if (maxLat - minLat) < needY {
		minLat, maxLat = midLat-needY/2, midLat+needY/2
	}
	return Proj{
		MinLon: minLon, MinLat: minLat, MaxLon: maxLon, MaxLat: maxLat,
		X: x, Y: y, W: w, H: h, CosRef: cosRef,
		SX: w / ((maxLon - minLon) * cosRef),
		SY: h / (maxLat - minLat),
	}
}

// Project maps (lon, lat) to pixel coordinates (origin top-left, y down).
func (p Proj) Project(lon, lat float64) (x, y float64) {
	x = p.X + (lon-p.MinLon)*p.CosRef*p.SX
	y = p.Y + (p.MaxLat-lat)*p.SY
	return x, y
}

// Unproject inverts Project (for tests).
func (p Proj) Unproject(x, y float64) (lon, lat float64) {
	lon = p.MinLon + (x-p.X)/p.CosRef/p.SX
	lat = p.MaxLat - (y-p.Y)/p.SY
	return lon, lat
}

// --- Name matching ---

// ncrDistricts are the geoBoundaries ADM2 names inside Metro Manila.
var ncrDistricts = map[string]bool{
	"ncr, city of manila, first district": true,
	"ncr, second district":                true,
	"ncr, third district":                 true,
	"ncr, fourth district":                true,
}

// NormalizeName maps a CAP areaDesc or basemap shapeName to a canonical key:
// lowercase, accent-folded, "province of" stripped, multi-space collapsed.
// Any NCR district name (or "metro manila"/"ncr ..."/"national capital
// region" and CAP areaDesc variants) maps to "metro manila".
func NormalizeName(s string) string {
	n := strings.ToLower(s)
	n = strings.Map(func(r rune) rune {
		switch r {
		case 'ñ':
			return 'n'
		case 'á', 'à', 'â', 'ä', 'ã', 'å':
			return 'a'
		case 'é', 'è', 'ê', 'ë':
			return 'e'
		case 'í', 'ì', 'î', 'ï':
			return 'i'
		case 'ó', 'ò', 'ô', 'ö', 'õ':
			return 'o'
		case 'ú', 'ù', 'û', 'ü':
			return 'u'
		case 'ç':
			return 'c'
		}
		return r
	}, n)
	n = strings.Join(strings.Fields(n), " ")
	n = strings.TrimPrefix(n, "province of ")
	n = strings.TrimSuffix(n, " province")
	if ncrDistricts[n] || strings.HasPrefix(n, "ncr") || strings.Contains(n, "ncr") || strings.Contains(n, "metro manila") || strings.Contains(n, "national capital") {
		return "metro manila"
	}
	return n
}
